function sessionCards(rows=state.sessions){if(!rows.length)return '<div class="empty">لا توجد جلسات.</div>';return rows.map(s=>{let statusText=s.status==='open'?'مفتوحة':s.status==='closed'?'مرفوعة':s.status==='cancelled'?'ملغاة':'مسجلة',actions='';if(roleCanManage()){if(s.status==='closed')actions=`<button class="mini" onclick="reopenSession('${s.id}')">تعديل الجلسة</button><button class="mini" onclick="editSessionData('${s.id}')">تعديل بيانات الجلسة</button><button class="mini red" onclick="cancelSession('${s.id}')">حذف الجلسة نهائياً</button>`;else if(s.status==='cancelled')actions=`<button class="mini red" onclick="cancelSession('${s.id}')">حذف نهائي</button>`;else actions=`<button class="mini" onclick="openSessionRoster('${s.id}')">فتح</button><button class="mini" onclick="editSessionData('${s.id}')">تعديل بيانات الجلسة</button><button class="mini" onclick="uploadSession('${s.id}')">رفع الجلسة</button><button class="mini red" onclick="cancelSession('${s.id}')">حذف الجلسة نهائياً</button>`}return `<div class="card"><div class="row"><div class="avatar">${s.session_type==='sard'?'س':'ت'}</div><div class="grow"><b>${esc(s.title||sesAr[s.session_type])}</b><div class="muted">${s.session_date} · ${sesAr[s.session_type]} · ${statusText} ${s._offline?'· محفوظ محلياً':''}</div>${sessionActivitySummaryHtml(s)}</div></div>${actions?`<div class="actions" style="margin-top:10px">${actions}${s.session_type==='lesson'&&['weekly','biweekly'].includes(sessionActivityData(s).recurrence)?`<button class="mini" onclick="duplicateActivitySession('${s.id}')">نسخ للموعد القادم</button>`:''}</div>`:''}</div>`}).join('')}
function sessionActivityData(se){let d=se?.activity_data;return d&&typeof d==='object'&&!Array.isArray(d)?d:{}}
