async function cancelSession(id){if(!roleCanManage())return;let se=state.sessions.find(x=>String(x.id)===String(id));if(!se)return;if(!confirm(`حذف جلسة «${se.title||sesAr[se.session_type]||'الجلسة'}» نهائياً؟\nسيتم حذف الجلسة وكل الحضور والتسميع والسلوك المرتبط بها.`))return;if(!confirm('تأكيد أخير: لا يمكن استرجاع هذه الجلسة بعد الحذف. متابعة؟'))return;let local=isLocalSessionId(id);if(local||!navigator.onLine||state.offline){removeSessionFromDevice(id,{queueServerDelete:!local});clearDeletedSessionDerivedState();toast(local?'تم حذف الجلسة المحلية وجميع بياناتها':'تم حذف الجلسة على الجهاز وسيُؤكد الحذف تلقائياً عند عودة الإنترنت');render();if(navigator.onLine)setTimeout(()=>syncOfflineQueue({refreshAfter:false}),30);return}try{let {data,error}=await db.from('sessions').delete().eq('id',id).select('id');if(error)throw error;if(!data?.length)throw new Error('لم تسمح الصلاحيات بحذف الجلسة');removeSessionFromDevice(id);clearDeletedSessionDerivedState();await loadAll();toast('تم حذف الجلسة نهائياً');render()}catch(e){if(isNetworkError(e)){removeSessionFromDevice(id,{queueServerDelete:true});clearDeletedSessionDerivedState();toast('انقطع الاتصال؛ تم حفظ طلب حذف الجلسة وسيكتمل تلقائياً');render()}else toast('تعذر حذف الجلسة: '+(e?.message||e))}}
function openSession(id=null){if(!state.halaqas.length)return setupFirstHalaqa();let se=id?state.sessions.find(x=>String(x.id)===String(id)):null;fillHalaqas($('#sessionHalaqa'));sessionDlg.dataset.editId=se?.id||'';let title=$('#sessionDlg h3'),saveBtn=$('#sessionForm .form-actions .btn-primary');if(se){if(title)title.textContent='تعديل بيانات الجلسة';if(saveBtn)saveBtn.textContent='حفظ التعديلات';$('#sessionHalaqa').value=se.halaqa_id||'';$('#sessionDate').value=se.session_date||today();$('#sessionType').value=se.session_type||'tasmee';$('#sessionTitle').value=se.title||'';$('#sessionNotes').value=se.notes||'';let ad=sessionActivityData(se);$('#sessionActivityType').value=ad.activity_type||'story';$('#sessionWeeklyValue').value=ad.weekly_value||'';$('#sessionQuizQuestions').value=String(ad.quiz_questions||0);$('#sessionQuizMax').value=String(ad.quiz_max||10);$('#sessionRecurrence').value=ad.recurrence||'once';$('#sessionActivityQuestions').value=activityQuestionsText(ad);$('#sessionActivitySummary').value=ad.summary||''}else{if(title)title.textContent='جلسة جديدة';if(saveBtn)saveBtn.textContent='حفظ وفتح الجلسة';$('#sessionDate').value=today();$('#sessionType').value='tasmee';$('#sessionTitle').value='';$('#sessionNotes').value='';$('#sessionActivityType').value='story';$('#sessionWeeklyValue').value='';$('#sessionQuizQuestions').value='0';$('#sessionQuizMax').value='10';$('#sessionRecurrence').value='once';$('#sessionActivityQuestions').value='';$('#sessionActivitySummary').value=''}updateSessionActivityFields();sessionDlg.showModal()}
