function saveSessionOfflineFirst(se){let idx=state.sessions.findIndex(x=>String(x.id)===String(se.id));if(idx>=0)Object.assign(state.sessions[idx],se);else state.sessions.unshift(se);let obj=sessionSaveObject(se);enqueueOffline({type:'session',key:`session:${se.id}`,dedupeKey:`session:${se.id}`,localId:se.id,intent:'status',obj});cacheSnapshot();render();if(navigator.onLine)setTimeout(()=>syncOfflineQueue({refreshAfter:false}),30)}
