async function reopenSession(id){if(!roleCanManage())return;let se=state.sessions.find(x=>String(x.id)===String(id));if(!se)return;let offlineNow=!state.networkVerified||state.offline||!navigator.onLine;if(offlineNow&&!isLocalSessionId(id)&&!sessionRosterCachedForOffline(id))return toast('لا يمكن فتح هذه الجلسة للتعديل دون إنترنت قبل تنزيل تفاصيلها. افتحها مرة أثناء الاتصال أولاً.');if(se.status!=='open'){if(!confirm('فتح الجلسة للتعديل مرة أخرى؟'))return;se.status='open';saveSessionOfflineFirst(se)}await openSessionRoster(id)}

$('#sessionForm').addEventListener('submit',async e=>{e.preventDefault();let editId=sessionDlg.dataset.editId||'',lesson=$('#sessionType').value==='lesson',activity_data=lesson?sessionActivityDataFromForm():{},base={halaqa_id:$('#sessionHalaqa').value,session_date:$('#sessionDate').value,session_type:$('#sessionType').value,title:$('#sessionTitle').value||null,notes:$('#sessionNotes').value||null,activity_data};if(editId){let se=state.sessions.find(x=>String(x.id)===String(editId));if(!se)return toast('الجلسة غير موجودة');if(!navigator.onLine||state.offline)return toast('تعديل تاريخ أو بيانات جلسة يحتاج اتصالًا لحماية الخطط والشارات');const btn=e.submitter;if(btn)btn.disabled=true;try{const row=await window.HalaqatiSessionServer.save(db,{intent:'edit',localId:se.id,obj:{...se,...base}});Object.assign(se,row);sessionDlg.close();sessionDlg.dataset.editId='';clearDeletedSessionDerivedState();await loadAll();render();toast('تم تعديل الجلسة وتحديث بياناتها المرتبطة')}catch(err){toast('تعذر التعديل: '+(err.message||err))}finally{if(btn)btn.disabled=false}return}let obj={...base,status:'open',created_by:state.user.id};if(state.demo){let data={...obj,id:'se'+Date.now()};state.sessions.unshift(data);sessionDlg.close();state.sessionView=data.id;state.sessionRoster={attendance:[],notes:[],recitations:[]};return render()}let localId=offlineUuid(),data={...obj,id:localId,_offline:true};enqueueOffline({type:'session',key:'session:'+localId,dedupeKey:'session:'+localId,localId,intent:'create',obj:{...obj,id:localId}});state.offlineRosterCache[localId]={attendance:[],notes:[],recitations:[]};state.sessions.unshift(data);sessionDlg.close();sessionDlg.dataset.editId='';state.sessionView=data.id;state.sessionRoster={attendance:[],notes:[],recitations:[]};cacheSnapshot();render();if(navigator.onLine)setTimeout(()=>syncOfflineQueue({refreshAfter:false}),30)})
function sessionRosterCachedForOffline(id){return !!state.offlineRosterCache?.[id]}
function pendingRosterStudentsForSession(id){
  let out={attendance:new Set(),notes:new Set(),reports:new Set()};
  for(let op of readOfflineQueue()){
    if(String(sessionIdForOfflineOp(op)||'')!==String(id))continue;
    if(op.type==='attendance'&&op.payload?.student_id)out.attendance.add(String(op.payload.student_id));
    if(op.type==='behavior'&&op.payload?.student_id)out.notes.add(String(op.payload.student_id));
    if(op.type==='report'&&op.payload?.studentId)out.reports.add(String(op.payload.studentId))
  }
  return out
}
function mergeSessionRosterCache(server={},cached={},sessionId=''){
  let attendance=[...(server.attendance||[])],notes=[...(server.notes||[])],recitations=[...(server.recitations||[])],pending=pendingRosterStudentsForSession(sessionId);
  let am=new Map(attendance.map(x=>[String(x.student_id),x]));
  for(let x of cached.attendance||[])if(x?._offline&&(pending.attendance.has(String(x.student_id))||pending.reports.has(String(x.student_id))))am.set(String(x.student_id),x);
  let nm=new Map(notes.map(x=>[String(x.student_id),x]));
  for(let x of cached.notes||[])if(x?._offline&&(pending.notes.has(String(x.student_id))||pending.reports.has(String(x.student_id))))nm.set(String(x.student_id),x);
  let localRec=(cached.recitations||[]).filter(x=>x?._offline&&pending.reports.has(String(x.student_id))),localStudents=new Set(localRec.map(x=>String(x.student_id)));
  if(localStudents.size)recitations=recitations.filter(x=>!localStudents.has(String(x.student_id)));
  recitations.push(...localRec);
  return {attendance:[...am.values()],notes:[...nm.values()],recitations}
}
function persistSessionRosterCache(id,roster){
  state.offlineRosterCache[id]=cloneJson(roster||{attendance:[],notes:[],recitations:[]});
  cacheSnapshot()
}
async function openSessionRoster(id){
  let needsCached=(!state.networkVerified||state.offline||!navigator.onLine)&&!isLocalSessionId(id);
  if(needsCached&&!sessionRosterCachedForOffline(id)){
    toast('تفاصيل هذه الجلسة غير محفوظة على الجهاز بعد. افتحها مرة أثناء الاتصال ليتم تنزيلها للعمل دون إنترنت.');
    return
  }
  state.page='sessions';state.sessionView=id;prepareSessionForOfflineWork(id);await loadSessionRosterData(id);render()
}
function closeSessionRoster(){state.sessionView=null;state.sessionRoster={attendance:[],notes:[],recitations:[]};render()}
async function loadSessionRosterData(id){
  let cached=state.offlineRosterCache[id];
  if(state.demo||!state.networkVerified||isLocalSessionId(id)||(state.user&&!(await ensureServerAuthSession({silent:true})))){
    state.sessionRoster=cached?cloneJson(cached):{attendance:[],notes:[],recitations:[]};return
  }
  let [a,n,r]=await Promise.all([
    db.from('attendance_records').select('*').eq('session_id',id),
    db.from('student_daily_notes').select('*').eq('session_id',id),
    db.from('recitation_entries').select('*').eq('session_id',id).order('created_at')
  ]);
  if((a.error&&isNetworkError(a.error))||(n.error&&isNetworkError(n.error))||(r.error&&isNetworkError(r.error))){
    state.offline=true;state.sessionRoster=cached?cloneJson(cached):{attendance:[],notes:[],recitations:[]};updateSyncBadge();return
  }
  let server={attendance:a.data||[],notes:n.data||[],recitations:r.data||[]};
  state.sessionRoster=mergeSessionRosterCache(server,cached||{},id);
  persistSessionRosterCache(id,state.sessionRoster)
}
async function cacheRecentSessionRostersForOffline(limit=30){
  if(state.demo||!roleCanManage()||!state.networkVerified||state.offline||!navigator.onLine||!state.user?.id)return 0;
  try{
    if(!(await ensureServerAuthSession({silent:true})))return 0;
    let rows=(state.sessions||[]).filter(x=>!isLocalSessionId(x.id)&&x.status!=='cancelled').sort((a,b)=>String(b.session_date||'').localeCompare(String(a.session_date||''))||String(b.created_at||'').localeCompare(String(a.created_at||''))).slice(0,Math.max(1,Number(limit)||30));
    let ids=rows.map(x=>x.id).filter(Boolean);if(!ids.length)return 0;
    let [a,n,r]=await Promise.all([
      db.from('attendance_records').select('*').in('session_id',ids),
      db.from('student_daily_notes').select('*').in('session_id',ids),
      db.from('recitation_entries').select('*').in('session_id',ids).order('created_at')
    ]);
    if(a.error||n.error||r.error){if([a.error,n.error,r.error].some(e=>e&&isNetworkError(e)))return 0;console.warn('Recent session offline cache skipped',a.error||n.error||r.error);return 0}
    let group=(arr,id)=>arr.filter(x=>String(x.session_id)===String(id));
    for(let id of ids){
      let server={attendance:group(a.data||[],id),notes:group(n.data||[],id),recitations:group(r.data||[],id)};
      state.offlineRosterCache[id]=cloneJson(mergeSessionRosterCache(server,state.offlineRosterCache[id]||{},id))
    }
    cacheSnapshot();return ids.length
  }catch(e){console.warn('Recent session offline cache failed',e);return 0}
}
window.cacheRecentSessionRostersForOffline=cacheRecentSessionRostersForOffline;
