function recitationRangeText(r){let mode=r.selection_data?.mode||r.input_method;if(r.start_surah&&r.end_surah){let a=`${surahs[r.start_surah-1]||'سورة'} ${r.start_ayah||''}`.trim(),b=`${surahs[r.end_surah-1]||'سورة'} ${r.end_ayah||''}`.trim();return a===b?a:`من ${a} إلى ${b}`}if(r.start_page||r.end_page){let a=r.start_page||r.end_page,b=r.end_page||r.start_page;return a===b?`صفحة ${fmt(a)}`:`صفحات ${fmt(a)}–${fmt(b)}`}if(Array.isArray(r.selected_surahs)&&r.selected_surahs.length)return r.selected_surahs.map(x=>surahs[x-1]).filter(Boolean).join('، ');let juz=r.selection_data?.selected_juz;if(Array.isArray(juz)&&juz.length)return `الأجزاء ${juz.join('، ')}`;if(Number(r.pages_count)>0)return `${fmt(r.pages_count)} صفحة`;return 'تم تسجيل التسميع'}
function recitationMiniCard(r){let ev=r.evaluation||r.rating||null,points=Number(r.points||0);return `<div class="roster-rec"><div class="roster-rec-type">${esc(actAr[r.activity_type]||r.activity_type)}</div><div><div class="roster-rec-range">${esc(recitationRangeText(r))}</div><div class="roster-rec-meta">${fmt(r.pages_count)} ص · ${r.mistakes||0} أخطاء · ${r.prompts||0} نقرات${ev?` · ${esc(evalAr[ev]||ev)}`:''}</div></div><div class="roster-rec-score">${points?`<b>${fmt(points)}</b><span class="muted">نقطة</span>`:''}</div></div>`}
function filterSessionRosterDom(v=''){state.sessionSearch=v;let q=normalizeNameJs(v),n=0;$$('[data-roster-name]').forEach(c=>{let show=!q||c.dataset.rosterName.includes(q);c.style.display=show?'':'none';if(show)n++});let x=$('#rosterVisibleCount');if(x)x.textContent=n;let empty=$('#rosterSearchEmpty');if(empty)empty.classList.toggle('hidden',n>0)}
