async function quickPresenceToggle(sid,seId,on){return quickAttendance(sid,seId,on?'present':'absent')}
async function quickAttendance(sid,seId,status,el=null){if(!status){if(el){let old=rosterAttendance(sid)?.status||'';el.value=old}return}let existing=rosterAttendance(sid),extra={};if(status==='excused'){let r=prompt('سبب العذر (اختياري):',existing?.excuse_reason||'');if(r===null){if(el)el.value=existing?.status||'';return}extra.excuse_reason=r||null}else if(status==='late'){let r=prompt('عدد دقائق التأخر (اختياري):',existing?.arrival_minutes_late||'');if(r===null){if(el)el.value=existing?.status||'';return}extra.arrival_minutes_late=Math.max(0,Number(r)||0)}else extra.excuse_reason=null;localAttendanceSave(sid,seId,status,extra);flashRosterCard(sid);render();if(navigator.onLine)setTimeout(()=>syncOfflineQueue({refreshAfter:false}),20)}
async function quickBehavior(sid,seId,behavior,el=null){localBehaviorSave(sid,seId,behavior);flashRosterCard(sid);render();if(navigator.onLine)setTimeout(()=>syncOfflineQueue({refreshAfter:false}),20)}
function flashRosterCard(sid){requestAnimationFrame(()=>{let c=document.getElementById('roster_'+sid);if(c){c.classList.remove('saved-flash');void c.offsetWidth;c.classList.add('saved-flash')}})}
async function quickOpenRecitation(sid,seId,type){await openDailyForStudent(sid,seId);addRecitationRow(type)}
function latestSession(){return state.sessions.find(s=>s.status==='open'&&s.session_date===today())||state.sessions.find(s=>s.status==='open')||null}
async function openDailyForStudent(sid,seId=null){let st=state.students.find(x=>x.id===sid),se=seId?state.sessions.find(x=>x.id===seId):latestSession();if(!se)return openSession();if(se.status==='closed'){toast('الجلسة مرفوعة. استخدم «تعديل الجلسة» أولاً.');return}let attendance=null,note=null,recs=[];if(state.sessionView===se.id){attendance=rosterAttendance(sid);note=rosterNote(sid);recs=rosterRecitations(sid)}else if(!state.demo&&state.networkVerified&&!isLocalSessionId(se.id)){let [a,n,r]=await Promise.all([db.from('attendance_records').select('*').eq('session_id',se.id).eq('student_id',sid).maybeSingle(),db.from('student_daily_notes').select('*').eq('session_id',se.id).eq('student_id',sid).maybeSingle(),db.from('recitation_entries').select('*').eq('session_id',se.id).eq('student_id',sid).order('created_at')]);attendance=a.data||null;note=n.data||null;recs=r.data||[]}else{let c=state.offlineRosterCache[se.id]||{attendance:[],notes:[],recitations:[]};attendance=c.attendance?.find(x=>x.student_id===sid)||null;note=c.notes?.find(x=>x.student_id===sid)||null;recs=(c.recitations||[]).filter(x=>x.student_id===sid)}$('#rpStudent').value=sid;$('#rpSession').value=se.id;$('#rpName').textContent=st.full_name;$('#rpAvatar').innerHTML=state.photoUrls[sid]?`<img src="${state.photoUrls[sid]}">`:st.full_name[0];$('#rpSessionLabel').textContent=`${se.session_date} · ${sesAr[se.session_type]}`;$('#rpAttendance').value=attendance?.status||'present';$('#rpExcuse').value=attendance?.excuse_reason||'';$('#rpBehavior').value=note?.behavior||'normal';$('#rpBehaviorScore').value=String(note?.behavior_score||behaviorScoreFor(note?.behavior||'normal'));$('#rpComment').value=note?.teacher_comment||'';$('#rpHomework').value=note?.homework||'';let activity=se.session_type==='lesson';$('#rpRecitationSection').classList.toggle('hidden',activity);$('#rpActivitySection').classList.toggle('hidden',!activity);$('#rpActivityScore').value=String(note?.activity_score||0);$('#rpActivityMax').value=String(note?.activity_max_score||sessionActivityData(se).quiz_max||10);$('#rpParticipation').value=note?.participation||'normal';$('#recitationRows').innerHTML='';state.reportExistingRecIds=recs.map(x=>x.id);if(!activity){if(recs.length)recs.forEach(addRecitationRowFromData);else addRecitationRow(se.session_type==='sard'?'sard':se.session_type==='review'?'review_near':'new_hifz')}reportDlg.showModal()}
function addRecitationRowFromData(rec){addRecitationRow(rec.activity_type||'new_hifz');let row=$$('#recitationRows .rec-row').at(-1),id=row.dataset.id;row.dataset.dbId=rec.id||'';row.dataset.pages=rec.pages_count||0;row.dataset.ayahs=rec.ayahs_count||0;row.dataset.surahs=rec.surahs_count||0;row.dataset.startPage=rec.start_page||'';row.dataset.endPage=rec.end_page||'';row.dataset.startSurah=rec.start_surah||'';row.dataset.startAyah=rec.start_ayah||'';row.dataset.endSurah=rec.end_surah||'';row.dataset.endAyah=rec.end_ayah||'';row.dataset.selectedSurahs=JSON.stringify(rec.selected_surahs||[]);row.dataset.selectedJuz=JSON.stringify(rec.selection_data?.selected_juz||[]);row.dataset.smartPlanId=rec.selection_data?.smart_plan_id||'';row.dataset.smartPlanType=rec.selection_data?.smart_plan_type||'';row.dataset.smartPlanDate=rec.selection_data?.smart_plan_date||'';row.dataset.tilawah=JSON.stringify(rec.selection_data?.tilawah_assessment||null);let mode=rec.selection_data?.mode||rec.input_method||'ayahs';if(!['ayahs','pages','surahs','juz'].includes(mode))mode=rec.start_page?'pages':'ayahs';row.dataset.mode=mode;row.querySelector('.rType').value=rec.activity_type||'new_hifz';row.querySelectorAll('.rec-body>.tabs .tab').forEach(b=>b.classList.remove('active'));let typeBtns=[...row.querySelectorAll('.rec-body>.tabs .tab')],idx=rec.activity_type==='new_hifz'?0:String(rec.activity_type).includes('review')?1:rec.activity_type==='sard'?2:3;if(typeBtns[idx])typeBtns[idx].classList.add('active');let segBtns=[...row.querySelectorAll('.seg button')],midx={ayahs:0,pages:1,surahs:2,juz:3}[mode]??0;segBtns.forEach((b,i)=>b.classList.toggle('active',i===midx));row.querySelector('.rAyahs').classList.toggle('hidden',mode!=='ayahs');row.querySelector('.rPages').classList.toggle('hidden',mode!=='pages');row.querySelector('.rSurahs').classList.toggle('hidden',mode!=='surahs');row.querySelector('.rJuz').classList.toggle('hidden',mode!=='juz');if(rec.start_surah)$('#'+id+'SS').value=rec.start_surah;if(rec.start_ayah)$('#'+id+'SA').value=rec.start_ayah;if(rec.end_surah)$('#'+id+'ES').value=rec.end_surah;if(rec.end_ayah)$('#'+id+'EA').value=rec.end_ayah;if(rec.start_surah&&rec.end_surah&&Number(rec.start_surah)===Number(rec.end_surah)&&typeof syncAyahPickerFromFields==='function')syncAyahPickerFromFields(id);else if(rec.start_surah&&rec.end_surah&&Number(rec.start_surah)!==Number(rec.end_surah)){let summary=$('#'+id+'AyahPickerSummary');if(summary)summary.textContent=`نطاق محفوظ متعدد السور: ${surahs[rec.start_surah-1]} ${rec.start_ayah} ← ${surahs[rec.end_surah-1]} ${rec.end_ayah}`;}if(rec.start_page)$('#'+id+'PF').value=rec.start_page;if(rec.end_page)$('#'+id+'PT').value=rec.end_page;(rec.selected_surahs||[]).forEach(n=>$('#'+id+'Surah'+n)?.classList.add('active'));(rec.selection_data?.selected_juz||[]).forEach(n=>$('#'+id+'J'+n)?.classList.add('active'));row.querySelector('.rPagesCount').textContent=fmt(rec.pages_count||0);row.querySelector('.rAyahsCount').textContent=rec.ayahs_count?`· ${rec.ayahs_count} آية`:'';row.querySelector('.rCalcStatus').textContent='بيانات محفوظة — يمكنك تعديلها';row.querySelector('.rMist').textContent=rec.mistakes||0;row.querySelector('.rPrompt').textContent=rec.prompts||0;row.querySelector('.rNote').value=rec.teacher_note||'';updateEval(row)}
function recId(){return 'rr'+Math.random().toString(36).slice(2,9)}
function addRecitationRow(type='new_hifz'){let id=recId(),d=document.createElement('div');d.className='card rec-row';d.dataset.id=id;d.dataset.pages='0';d.dataset.ayahs='0';d.dataset.surahs='0';d.dataset.startPage='';d.dataset.endPage='';d.dataset.mode='ayahs';d.innerHTML=`<div class="rec-head"><div><b>بند تسميع</b><div class="muted">اختر النوع وطريقة تحديد المقدار</div></div><button class="mini red" type="button" onclick="this.closest('.rec-row').remove()">حذف</button></div><div class="rec-body"><div class="tabs"><button class="tab ${type==='new_hifz'?'active':''}" type="button" onclick="setRecType(this,'new_hifz')">حفظ</button><button class="tab ${type.includes('review')?'active':''}" type="button" onclick="setRecType(this,'review_near')">مراجعة</button><button class="tab ${type==='sard'?'active':''}" type="button" onclick="setRecType(this,'sard')">سرد</button><button class="tab" type="button" onclick="setRecType(this,'tilawah')">تلاوة</button><button class="tab ${type==='test'?'active':''}" type="button" onclick="setRecType(this,'test')">اختبار</button></div><input type="hidden" class="rType" value="${type}"><div class="seg"><button class="active" type="button" onclick="setRecMode(this,'ayahs')">السورة والآية</button><button type="button" onclick="setRecMode(this,'pages')">الصفحات</button><button type="button" onclick="setRecMode(this,'surahs')">سور متعددة</button><button type="button" onclick="setRecMode(this,'juz')">الأجزاء</button></div><div class="rAyahs mode-panel">${qAyahPanel(id,true)}</div><div class="rPages mode-panel hidden">${qPagesPanel(id,true)}</div><div class="rSurahs mode-panel hidden">${qSurahsPanel(id,true)}</div><div class="rJuz mode-panel hidden">${qJuzPanel(id,true)}</div><div class="actions"><button class="btn btn-soft" type="button" onclick="calcRecRow(this.closest('.rec-row'))">حساب المقدار</button><button class="btn btn-ghost" type="button" onclick="openRowMushaf(this.closest('.rec-row'))">📖 فتح المصحف</button></div><div class="range-summary"><span class="muted">المقدار الفعلي</span><div><strong class="rPagesCount">0</strong> صفحة <span class="muted rAyahsCount"></span></div><div class="calc-status rCalcStatus">اختر النطاق ثم اضغط حساب المقدار</div></div><div class="form-grid"><label class="field"><span>عدد الأخطاء</span><div class="counter"><button type="button" onclick="stepCounter(this,1,'mist')">＋</button><div class="num rMist">0</div><button type="button" onclick="stepCounter(this,-1,'mist')">−</button></div></label><label class="field"><span>عدد النقرات / التلقينات</span><div class="counter"><button type="button" onclick="stepCounter(this,1,'prompt')">＋</button><div class="num rPrompt">0</div><button type="button" onclick="stepCounter(this,-1,'prompt')">−</button></div></label></div><div class="eval-box"><div class="row"><span class="eval-dot eval-excellent rEvalDot"></span><div><b class="rEvalText">غير مقيّم</b><div class="muted rEvalMeta">التقييم يتغير حسب الخصم لكل صفحة</div></div></div><div style="text-align:left"><b class="rPoints">0</b><div class="muted">نقطة</div></div></div><label class="field"><span>ملاحظة خاصة بهذا التسميع</span><input class="input rNote" placeholder="اختياري"></label></div>`;$('#recitationRows').appendChild(d);if(typeof updateAyahPickerRangeVisual==='function')updateAyahPickerRangeVisual(id);updateEval(d)}
function setRecType(btn,type){let row=btn.closest('.rec-row');row.querySelectorAll('.tabs .tab').forEach(x=>x.classList.remove('active'));btn.classList.add('active');row.querySelector('.rType').value=type;if(typeof rc27SyncTilawah==='function')rc27SyncTilawah(row)}
function setRecMode(btn,mode){let row=btn.closest('.rec-row');row.dataset.mode=mode;btn.parentElement.querySelectorAll('button').forEach(x=>x.classList.remove('active'));btn.classList.add('active');row.querySelector('.rAyahs').classList.toggle('hidden',mode!=='ayahs');row.querySelector('.rPages').classList.toggle('hidden',mode!=='pages');row.querySelector('.rSurahs').classList.toggle('hidden',mode!=='surahs');row.querySelector('.rJuz').classList.toggle('hidden',mode!=='juz')}
function stepCounter(btn,delta,kind){let row=btn.closest('.rec-row'),el=row.querySelector(kind==='mist'?'.rMist':'.rPrompt');el.textContent=Math.max(0,+el.textContent+delta);updateEval(row)}
function computeEval(pages,mist,prompt){let d=typeof window.computeRecitationV6==='function'?window.computeRecitationV6(pages,mist,prompt):typeof window.computeRecitationV5==='function'?window.computeRecitationV5(pages,mist,prompt):null;if(d)return {penalty:d.penalty_units,density:d.penalty_per_page,safety:d.safety_percentage,ev:d.evaluation,points:d.points,scoringVersion:d.scoring_version};let p=Math.max(Number(pages)||0,0),m=Math.max(Number(mist)||0,0),pr=Math.max(Number(prompt)||0,0),lines=p*15,units=m+(pr*.5),normalized=lines>0?units*15/lines:0,safety=lines>0?Math.max(0,100-normalized*20):0,ev=p<=0?'not_rated':safety>=90?'excellent':safety>=80?'very_good':safety>=70?'good':'repeat',points=p<=0?0:Math.max(0,p-(units*.25));return {penalty:units,density:p?units/p:0,safety,ev,points:Math.round(points*100)/100,scoringVersion:'V6'}}
function updateEval(row){let d=computeEval(+row.dataset.pages||0,+row.querySelector('.rMist').textContent,+row.querySelector('.rPrompt').textContent);row.querySelector('.rEvalText').textContent=evalAr[d.ev];row.querySelector('.rEvalDot').className='eval-dot rEvalDot '+evalDot(d.ev==='not_rated'?'repeat':d.ev);row.querySelector('.rPoints').textContent=fmt(d.points);row.querySelector('.rEvalMeta').textContent=d.density==null?'حدد مقدار التسميع أولاً':`سلامة ${fmt(d.safety)}% · أخطاء موزونة ${fmt(d.penalty)} · ${fmt(d.density)} لكل صفحة تقييم`;row.dataset.evaluation=d.ev;row.dataset.points=d.points;row.dataset.penalty=d.penalty;row.dataset.penaltyPerPage=d.density??''}
function openRowMushaf(row){let id=row.dataset.id,s=+row.dataset.startSurah||+$('#'+id+'SS')?.value||1,a=+row.dataset.startAyah||+$('#'+id+'SA')?.value||1;window.open(`https://quran.com/${s}/${a}`,'_blank')}
async function calcRecRow(row){let id=row.dataset.id,mode=row.dataset.mode;try{row.querySelector('.rCalcStatus').textContent='جاري الحساب...';let d,selectedSurahs=[],selectedJuz=[];if(mode==='pages'){let a=+$('#'+id+'PF').value,b=+$('#'+id+'PT').value;if(!a||!b||b<a)throw new Error('تحقق من الصفحات');if(row.dataset.startSurah&&row.dataset.endSurah)d=await calculateAyahRangeData(+row.dataset.startSurah,+row.dataset.startAyah,+row.dataset.endSurah,+row.dataset.endAyah);else d={pages:b-a+1,ayahs:0,surahs:0,startPage:a,endPage:b};row.dataset.startPage=a;row.dataset.endPage=b}else if(mode==='surahs'){selectedSurahs=selectedNums(id,'surah');if(!selectedSurahs.length)throw new Error('اختر سورة واحدة على الأقل');d=await calculateFullSurahs(selectedSurahs);d.surahs=selectedSurahs.length}else if(mode==='juz'){selectedJuz=selectedNums(id,'juz');if(!selectedJuz.length)throw new Error('اختر جزءاً واحداً على الأقل');d=await calculateJuzs(selectedJuz);d.surahs=0}else{let ss=+$('#'+id+'SS').value,sa=+$('#'+id+'SA').value,es=+$('#'+id+'ES').value,ea=+$('#'+id+'EA').value;d=await calculateAyahRangeData(ss,sa,es,ea);row.dataset.startSurah=ss;row.dataset.endSurah=es;row.dataset.startAyah=sa;row.dataset.endAyah=ea}row.dataset.pages=d.pages;row.dataset.ayahs=d.ayahs||0;row.dataset.surahs=d.surahs||0;row.dataset.selectedSurahs=JSON.stringify(selectedSurahs);row.dataset.selectedJuz=JSON.stringify(selectedJuz);if(d.startPage)row.dataset.startPage=d.startPage;if(d.endPage)row.dataset.endPage=d.endPage;row.querySelector('.rPagesCount').textContent=fmt(d.pages);row.querySelector('.rAyahsCount').textContent=d.ayahs?`· ${d.ayahs} آية`:'';row.querySelector('.rCalcStatus').textContent=d.preciseLines?'محسوب محلياً حسب سطور مصحف المدينة (15 سطراً)':d.estimated?'تقدير احتياطي؛ بيانات المصحف الدقيقة غير جاهزة':'تم حساب المقدار';updateEval(row)}catch(e){row.querySelector('.rCalcStatus').textContent=e.message;toast(e.message)}}
$('#reportForm').addEventListener('submit',async e=>{e.preventDefault();let sid=$('#rpStudent').value,seId=$('#rpSession').value,attendance={session_id:seId,student_id:sid,status:$('#rpAttendance').value,excuse_reason:$('#rpExcuse').value||null,recorded_by:state.user.id},note={session_id:seId,student_id:sid,behavior:$('#rpBehavior').value,behavior_score:+$('#rpBehaviorScore').value,teacher_comment:$('#rpComment').value||null,homework:$('#rpHomework').value||null,activity_score:+$('#rpActivityScore').value||0,activity_max_score:+$('#rpActivityMax').value||0,participation:$('#rpParticipation').value||'normal',parent_visible:true,created_by:state.user.id};let lesson=state.sessions.find(x=>String(x.id)===String(seId))?.session_type==='lesson',formRows=(lesson?[]:$$('.rec-row')).map(r=>{let inferredPlan=!r.dataset.smartPlanId&&typeof window.halaqatiResolveSmartPlanForRecitation==='function'?window.halaqatiResolveSmartPlanForRecitation({studentId:sid,sessionId:seId,activityType:r.querySelector('.rType').value,startPage:+r.dataset.startPage||null,endPage:+r.dataset.endPage||null}):null;let data={session_id:seId,student_id:sid,activity_type:r.querySelector('.rType').value,input_method:r.dataset.mode,start_surah:+r.dataset.startSurah||null,start_ayah:+r.dataset.startAyah||null,end_surah:+r.dataset.endSurah||null,end_ayah:+r.dataset.endAyah||null,start_page:+r.dataset.startPage||null,end_page:+r.dataset.endPage||null,pages_count:+r.dataset.pages||0,ayahs_count:+r.dataset.ayahs||0,surahs_count:+r.dataset.surahs||0,mistakes:+r.querySelector('.rMist').textContent||0,prompts:+r.querySelector('.rPrompt').textContent||0,teacher_note:r.querySelector('.rNote').value||null,selected_surahs:JSON.parse(r.dataset.selectedSurahs||'[]'),selection_data:{mode:r.dataset.mode,selected_juz:JSON.parse(r.dataset.selectedJuz||'[]'),start_global:r.dataset.startGlobal||null,end_global:r.dataset.endGlobal||null,qcf_line_keys:typeof window.halaqatiQcfLineKeysForRecitation==='function'?window.halaqatiQcfLineKeysForRecitation({mode:r.dataset.mode,startSurah:+r.dataset.startSurah||null,startAyah:+r.dataset.startAyah||null,endSurah:+r.dataset.endSurah||null,endAyah:+r.dataset.endAyah||null,startPage:+r.dataset.startPage||null,endPage:+r.dataset.endPage||null}):[],smart_plan_id:r.dataset.smartPlanId||inferredPlan?.id||null,smart_plan_type:r.dataset.smartPlanType||inferredPlan?.plan_type||null,smart_plan_date:r.dataset.smartPlanDate||state.sessions.find(x=>String(x.id)===String(seId))?.session_date||null},created_by:state.user.id};if(typeof rc27TilawahApply==='function')rc27TilawahApply(r,data);return {dbId:r.dataset.dbId||null,data:(typeof rc27AfterDecorate==='function'?rc27AfterDecorate(decorateRecForOffline(data)):decorateRecForOffline(data))}});let payload={sessionId:seId,studentId:sid,attendance,note,rows:formRows,existingRecIds:[...(state.reportExistingRecIds||[])]};if(state.demo){reportDlg.close();toast('تم حفظ التقرير التجريبي');return}saveReportOffline(payload);reportDlg.close();render();if(navigator.onLine)setTimeout(()=>syncOfflineQueue({refreshAfter:false}),30)})

function removeSessionFromDevice(id,{queueServerDelete=false}={}){let map=readSessionMap(),resolved=resolveSessionId(id,map),wasLocal=isLocalSessionId(id);state.sessions=state.sessions.filter(x=>String(x.id)!==String(id)&&String(x.id)!==String(resolved));delete state.offlineRosterCache[id];delete state.offlineRosterCache[resolved];let q=readOfflineQueue().filter(op=>{if(op.type==='delete_session')return String(sessionIdForOfflineOp(op)||'')!==String(id)&&String(sessionIdForOfflineOp(op)||'')!==String(resolved);let sid=sessionIdForOfflineOp(op);return String(sid||'')!==String(id)&&String(sid||'')!==String(resolved)&&!String(op.key||'').includes(String(id))});if(queueServerDelete&&!wasLocal){q.push(normalizeOfflineOperation({type:'delete_session',key:`delete-session:${resolved}`,dedupeKey:`delete-session:${resolved}`,payload:{session_id:resolved}}))}writeOfflineQueue(q);let recovery=readSyncRecoverySessions();delete recovery[id];delete recovery[resolved];writeSyncRecoverySessions(recovery);delete map[id];if(resolved!==id)delete map[resolved];writeSessionMap(map);if(state.sessionView===id||state.sessionView===resolved){state.sessionView=null;state.sessionRoster={attendance:[],notes:[],recitations:[]}}state.syncIssue='';state.authNeedsLogin=false;cacheSnapshot();updateSyncBadge()}
function clearDeletedSessionDerivedState(){if(navigator.onLine&&!state.offline){state.dailySummary=[];state.monthly=[];state.leaderDaily=[];state.leaderMonthly=[]}else state.sessionDerivedDirty=true;window.dispatchEvent(new CustomEvent('halaqati:sessionchange',{detail:{structural:true}}));cacheSnapshot()}
function sessionCards(rows=state.sessions){if(!rows.length)return '<div class="empty">لا توجد جلسات.</div>';return rows.map(s=>{let statusText=s.status==='open'?'مفتوحة':s.status==='closed'?'مرفوعة':s.status==='cancelled'?'ملغاة':'مسجلة',actions='';if(roleCanManage()){if(s.status==='closed')actions=`<button class="mini" onclick="reopenSession('${s.id}')">تعديل الجلسة</button><button class="mini" onclick="editSessionData('${s.id}')">تعديل بيانات الجلسة</button><button class="mini red" onclick="cancelSession('${s.id}')">حذف الجلسة نهائياً</button>`;else if(s.status==='cancelled')actions=`<button class="mini red" onclick="cancelSession('${s.id}')">حذف نهائي</button>`;else actions=`<button class="mini" onclick="openSessionRoster('${s.id}')">فتح</button><button class="mini" onclick="editSessionData('${s.id}')">تعديل بيانات الجلسة</button><button class="mini" onclick="uploadSession('${s.id}')">رفع الجلسة</button><button class="mini red" onclick="cancelSession('${s.id}')">حذف الجلسة نهائياً</button>`}return `<div class="card"><div class="row"><div class="avatar">${s.session_type==='sard'?'س':'ت'}</div><div class="grow"><b>${esc(s.title||sesAr[s.session_type])}</b><div class="muted">${s.session_date} · ${sesAr[s.session_type]} · ${statusText} ${s._offline?'· محفوظ محلياً':''}</div>${sessionActivitySummaryHtml(s)}</div></div>${actions?`<div class="actions" style="margin-top:10px">${actions}${s.session_type==='lesson'&&['weekly','biweekly'].includes(sessionActivityData(s).recurrence)?`<button class="mini" onclick="duplicateActivitySession('${s.id}')">نسخ للموعد القادم</button>`:''}</div>`:''}</div>`}).join('')}
async function cancelSession(id){if(!roleCanManage())return;let se=state.sessions.find(x=>String(x.id)===String(id));if(!se)return;if(!confirm(`حذف جلسة «${se.title||sesAr[se.session_type]||'الجلسة'}» نهائياً؟\nسيتم حذف الجلسة وكل الحضور والتسميع والسلوك المرتبط بها.`))return;if(!confirm('تأكيد أخير: لا يمكن استرجاع هذه الجلسة بعد الحذف. متابعة؟'))return;let local=isLocalSessionId(id);if(local||!navigator.onLine||state.offline){removeSessionFromDevice(id,{queueServerDelete:!local});clearDeletedSessionDerivedState();toast(local?'تم حذف الجلسة المحلية وجميع بياناتها':'تم حذف الجلسة على الجهاز وسيُؤكد الحذف تلقائياً عند عودة الإنترنت');render();if(navigator.onLine)setTimeout(()=>syncOfflineQueue({refreshAfter:false}),30);return}try{let {data,error}=await db.from('sessions').delete().eq('id',id).select('id');if(error)throw error;if(!data?.length)throw new Error('لم تسمح الصلاحيات بحذف الجلسة');removeSessionFromDevice(id);clearDeletedSessionDerivedState();await loadAll();toast('تم حذف الجلسة نهائياً');render()}catch(e){if(isNetworkError(e)){removeSessionFromDevice(id,{queueServerDelete:true});clearDeletedSessionDerivedState();toast('انقطع الاتصال؛ تم حفظ طلب حذف الجلسة وسيكتمل تلقائياً');render()}else toast('تعذر حذف الجلسة: '+(e?.message||e))}}
function recitationMiniCard(r){let ev=r.evaluation||r.rating||null,points=Number(r.points||0),del=roleCanManage()?(r._offline?'<span class="badge">محلي — احذفه من تعديل التفاصيل</span>':`<button class="mini red" type="button" onclick="deleteRecitationEntry('${r.id}')">حذف التسميع</button>`):'';return `<div class="roster-rec"><div class="roster-rec-type">${esc(actAr[r.activity_type]||r.activity_type)}</div><div><div class="roster-rec-range">${esc(recitationRangeText(r))}</div><div class="roster-rec-meta">${fmt(r.pages_count)} ص · ${r.mistakes||0} أخطاء · ${r.prompts||0} نقرات${ev?` · ${esc(evalAr[ev]||ev)}`:''}</div></div><div class="roster-rec-score">${points?`<b>${fmt(points)}</b><span class="muted">نقطة</span>`:''}</div>${del?`<div class="roster-rec-actions">${del}</div>`:''}</div>`}
async function deleteRecitationEntry(id){if(!roleCanManage())return;let r=(state.sessionRoster.recitations||[]).find(x=>x.id===id);if(!r)return toast('التسميع غير موجود');if(r._offline)return toast('التسميع محلي؛ افتح تعديل التفاصيل واحذف البند ثم احفظ');if(!confirm('حذف هذا التسميع نهائياً؟ سيُزال من نقاط الطالب وترتيبه وتقاريره.'))return;if(!navigator.onLine||state.offline)return toast('الحذف النهائي يحتاج اتصالاً بالإنترنت');try{let {data,error}=await db.from('recitation_entries').delete().eq('id',id).select('id');if(error)throw error;if(!data?.length)throw new Error('لم تسمح الصلاحيات بالحذف');state.sessionRoster.recitations=state.sessionRoster.recitations.filter(x=>x.id!==id);clearDeletedSessionDerivedState();await loadAll();if(state.sessionView)await loadSessionRosterData(state.sessionView);toast('تم حذف التسميع وتحديث التقارير');render()}catch(e){toast('تعذر حذف التسميع: '+(e?.message||e))}}

// RC18.2 archive preserves activity_data and server-derived history.
window.setSessionArchived=async function(id,archived){
 if(!roleCanManage())return;
 if(!navigator.onLine||state.offline)return toast('الأرشفة والاستعادة تحتاجان اتصالًا بالخادم');
 try{const row=await window.HalaqatiSessionServer.archive(db,id,archived);const se=state.sessions.find(x=>String(x.id)===String(id));if(se)Object.assign(se,row);clearDeletedSessionDerivedState();await loadAll();render();toast(archived?'تمت أرشفة الجلسة':'تمت استعادة الجلسة')}catch(e){toast('تعذرت العملية: '+e.message)}
};
const nativeSessionCards=sessionCards;
sessionCards=function(rows=state.sessions){return nativeSessionCards(rows).replace(/(<button class="mini" onclick="editSessionData\('([^']+)'\)"[^>]*>[^<]*<\/button>)/g,(all,button,id)=>{const se=rows.find(x=>String(x.id)===id);return button+`<button class="mini" onclick="setSessionArchived('${id}',${!se?.activity_data?.archived})">${se?.activity_data?.archived?'استعادة من الأرشيف':'أرشفة'}</button>`})};
